package io.knowledgebrain.brainquery;
import java.util.*;
import io.knowledgebrain.contracts.knowledge.publicknowledge.v1.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
class PublicProjectionTest {
 static final String ID="019a0000-0000-7000-8000-000000000001",SPACE="019a0000-0000-7000-8000-000000000002",ACTOR="019a0000-0000-7000-8000-000000000003",REV="019a0000-0000-7000-8000-000000000004",EVENT="019a0000-0000-7000-8000-000000000005";
 static byte[] wire(String visibility,String kind,String content,String pins,long version){var p=PublicKnowledgeChangedPayloadV1.newBuilder().setEntityId(ID).setKind(kind).setVersion(version).setState("ACTIVE").setTitle("Public").setContentJson(content).setQualifierPinsJson(pins).setRevisionId(REV).setVisibility(visibility).build();return EventEnvelopeV1.newBuilder().setEventId(EVENT).setProducer("knowledge-service").setAggregateType("PublicKnowledge").setAggregateId(ID).setSpaceId(SPACE).setActorId(ACTOR).setOccurredAtEpochMillis(1793520000000L).setEventVersion(1).setEventType("PublicKnowledgeChanged").setTraceId("a".repeat(32)).setPayload(p.toByteString()).build().toByteArray();}
 @Test void publicOnlyAndExactEnvelopeAndDuplicateJsonValidation()throws Exception{assertThatThrownBy(()->PublicProjection.decode(wire("PRIVATE","CONCEPT","{}","{}",1),ID,null)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->PublicProjection.decode(wire("PUBLIC","CONCEPT","{\"x\":1,\"x\":2}","{}",1),ID,null)).isInstanceOf(IllegalArgumentException.class);var bytes=wire("PUBLIC","CONCEPT","{}","{}",1);assertThatThrownBy(()->PublicProjection.decode(bytes,SPACE,null)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->PublicProjection.decode(bytes,ID,Map.of())).isInstanceOf(IllegalArgumentException.class);assertThat(PublicProjection.decode(bytes,ID,null).space()).isEqualTo(UUID.fromString(SPACE));}
 @Test void canonicalHashSurvivesJsonbOrderAndIntegerWidth(){var a=PublicProjection.decode(wire("PUBLIC","CONCEPT","{\"a\":1,\"b\":\"same\"}","{}",1),ID,null);var b=PublicProjection.decode(wire("PUBLIC","CONCEPT","{\"b\":\"same\",\"a\":1}","{}",1),ID,null);assertThat(a.hash()).isEqualTo(b.hash());}
 @Test void literalQualifierDoesNotProduceFakeConceptVertex(){var c=PublicProjection.JSON.readTree("{\"claimId\":\""+ID+"\",\"predicateId\":\""+ACTOR+"\",\"valueType\":\"STRING\",\"value\":\""+SPACE+"\"}");assertThat(PublicProjection.references("QUALIFIER",c)).extracting(PublicProjection.Ref::role).containsExactly("QUALIFIES","QUALIFIER_PREDICATE");((tools.jackson.databind.node.ObjectNode)c).put("valueType","CONCEPT");assertThat(PublicProjection.references("QUALIFIER",c)).hasSize(3);}
 @Test void staleOrRetiredCanonicalRowsNeverCountAsCurrent(){var item=new PublicCanonicalClient.Item(UUID.fromString(ID),"CONCEPT","Title",2,"ACTIVE",PublicProjection.JSON.createObjectNode(),PublicProjection.JSON.createObjectNode(),true,"",false);assertThat(PublicDiscoveryController.current(item,"CONCEPT",1)).isFalse();assertThat(PublicDiscoveryController.current(item,"CLAIM",2)).isFalse();assertThat(PublicDiscoveryController.current(item,"CONCEPT",2)).isTrue();}
 @Test void poisonedSearchSpaceAndDuplicateIdsFailClosed(){String row="{\"_id\":\""+ID+"\",\"_source\":{\"entityId\":\""+ID+"\",\"kind\":\"CONCEPT\",\"canonicalVersion\":1,\"spaceId\":\""+SPACE+"\",\"state\":\"ACTIVE\",\"visibility\":\"PUBLIC\"}}";var hits=PublicProjection.JSON.readTree("{\"total\":{\"value\":2,\"relation\":\"eq\"},\"hits\":["+row+","+row+"]}");assertThatThrownBy(()->PublicDiscoveryController.projected(hits,UUID.fromString(SPACE),null,0,20)).isInstanceOf(NoteSearchClient.Unavailable.class);assertThatThrownBy(()->PublicDiscoveryController.projected(hits,UUID.fromString(ACTOR),null,0,20)).isInstanceOf(NoteSearchClient.Unavailable.class);}
 @Test void existingMaximumConceptTextRemainsProjectableAfterJsonEscaping(){String description="\u001f".repeat(32768);String content=PublicProjection.JSON.createObjectNode().put("description",description).toString();byte[] bytes=wire("PUBLIC","CONCEPT",content,"{}",1);assertThat(bytes.length).isGreaterThan(65536);assertThat(PublicProjection.decode(bytes,ID,null).content().path("description").asString()).isEqualTo(description);}

}
